    fund_gp_name,
    fund_asset_class,
    fund_strategy,
    fund_vintage_year,
    fund_committed_capital_usd,
    fund_currency,
    fund_domicile,
    fund_status,
    fund_reported_on,
    fund_gp_business_key,
    fund_external_identity,
    coalesce(fund_business_key is null, true) as violation_00,
    coalesce(fund_business_key is not null and count(*) over (partition by fund_business_key) > 1, true) as violation_01
from curation_survivor
